SELECT 'decide' AS check_name, answer AS needs_refund, status FROM thinkthen_decide((SELECT 'Please refund the duplicate charge.' AS record), 'Does the customer request a refund?');
SELECT 'choose' AS check_name, answer AS owning_team, status FROM thinkthen_choose((SELECT 'Please refund the duplicate charge.' AS record), 'Which team owns this?', choices := ['billing','shipping','account']);
SELECT 'tag' AS check_name, answer AS customer_topics, status FROM thinkthen_tag((SELECT 'Please refund the duplicate charge.' AS record), 'Which topics apply?', labels := ['refund','delivery','login']);
SELECT 'score' AS check_name, answer AS urgency_score, status FROM thinkthen_score((SELECT 'Please refund the duplicate charge.' AS record), 'How urgent is this?', levels := ['low','medium','high']);
SELECT 'filter' AS check_name, answer AS needs_refund, status FROM thinkthen_filter((SELECT body AS record FROM (VALUES ('Please refund the duplicate charge.'),('Thanks for the help.')) input(body)), 'Does the customer request a refund?');
SELECT 'rank' AS check_name, answer AS urgency_rank, status FROM thinkthen_rank((SELECT body AS record FROM (VALUES ('Please refund the duplicate charge.'),('Thanks for the help.')) input(body)), 'How urgent is this?', levels := ['low','medium','high']);
SELECT 'find' AS check_name, answer AS meeting_time, status FROM thinkthen_find((SELECT 'Please refund the duplicate charge.' AS record), 'When is the meeting?');
SELECT 'annotate' AS check_name, answer AS record_review, status FROM thinkthen_annotate((SELECT 'Please refund the duplicate charge.' AS record), questions := '{"refund": {"function": "decide", "question": "Does the customer request a refund?"}}'::JSON);
SELECT 'recognize' AS check_name, answer AS named_entities, status FROM thinkthen_recognize((SELECT 'Ada works for Acme.' AS record), kinds := ['person','organization']);
SELECT 'relate' AS check_name, answer AS employment_relations, status FROM thinkthen_relate((SELECT 'Ada works for Acme.' AS record), rules := [struct_pack(relation := 'works_for',source := 'person',target := 'organization')]);
